package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates set on a sheet for each grade, each in force from its from-date. A grade with no rate
 *  in force on a date on a sheet takes its parent sheet's, then the parent's parent's, up to
 *  {@link #PARENT_LEVELS} levels up. */
@Service
public class RateService {

    /** How many levels of parent sheets are looked to for a rate the sheet has none in force for. */
    public static final int PARENT_LEVELS = 3;

    private final RateRepository rates;
    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final History history;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, SheetRepository sheetRepository, History history,
            Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.history = history;
        this.audit = audit;
    }

    /** The sheet's parent sheet's id; null when it has none. The parent is not kept in the sheet's
     *  history: a sheet shown as of a past day falls back to its parent as it stands now. */
    private String parentOf(String sheetId) {
        return sheetRepository.findById(sheetId).map(Sheet::getParentId).orElse(null);
    }

    /** The sheets the sheet's rates fall back to, nearest first: its parent, the parent's parent, up
     *  to {@link #PARENT_LEVELS} levels up. */
    public List<String> ancestors(String sheetId) {
        List<String> found = new ArrayList<>();
        String sheet = parentOf(sheetId);
        while (sheet != null && found.size() < PARENT_LEVELS && !sheet.equals(sheetId) && !found.contains(sheet)) {
            found.add(sheet);
            sheet = parentOf(sheet);
        }
        return found;
    }

    /** The sheet's rates by grade, each grade's from the earliest. */
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromAscIdAsc(sheetId);
    }

    /** The sheet's rates by grade, each grade's from the earliest, as they stood at the end of a day
     *  (null: as they stand now). */
    public List<Rate> list(String sheetId, LocalDate asOf) {
        if (asOf == null) {
            return list(sheetId);
        }
        return Stream.of("A", "B", "C")
                .flatMap(grade -> history.rates(sheetId, grade, asOf).stream()
                        .sorted(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()))))
                .toList();
    }

    /** The grade's rate in force on a date: the one whose from-date is the latest on or before it
     *  (a rate with no from-date applies from the beginning of time); none applies when there is no
     *  such rate, or when that one's to-date is before the date. When none applies on the sheet, the
     *  parent sheet's is taken, then the parent's parent's, up to {@link #PARENT_LEVELS} levels up;
     *  empty when none applies on any of them. */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return rateOn(sheetId, grade, date, null);
    }

    /** The grade's rate in force on a date as the rates (the sheet's and its parent sheets') stood
     *  at the end of a day (null: as they stand now). */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        Optional<Rate> own = ownRateOn(sheetId, grade, date, asOf);
        if (own.isPresent()) {
            return own;
        }
        for (String ancestor : ancestors(sheetId)) {
            Optional<Rate> theirs = ownRateOn(ancestor, grade, date, asOf);
            if (theirs.isPresent()) {
                return theirs;
            }
        }
        return Optional.empty();
    }

    private Optional<Rate> ownRateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        return inForce(asOf == null ? rates.findBySheetIdAndGradeOrderByFromAsc(sheetId, grade)
                : history.rates(sheetId, grade, asOf), date);
    }

    private static Optional<Rate> inForce(List<Rate> theirs, LocalDate date) {
        return theirs.stream()
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(rate -> !rate.endedBy(date));
    }

    /** Set the rate for a grade from a date (null: from the beginning of time) through a date (null:
     *  with no end), replacing the one the grade had from that date. A to-date before the from-date
     *  is refused. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId);
        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
        Optional<Rate> had = from == null
                ? rates.findBySheetIdAndGradeAndFromIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from);
        Rate saved = had
                .map(existing -> {
                    existing.setRate(scaled);
                    existing.setTo(to);
                    return existing;
                })
                .orElseGet(() -> new Rate(sheetId, grade, from, to, scaled));
        saved = rates.saveAndFlush(saved);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + saved.getRate().toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it; the rate is a percent string with two decimals, the
     *  from-date null when the rate applies from the beginning of time. */
    public record RateView(String grade, String rate, LocalDate from, LocalDate to) {
        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getRate().toPlainString(), rate.getFrom(), rate.getTo());
        }
    }

    /** A rate: a percent of 0.00 or more with up to two decimals, and the date it applies from
     *  (blank: from the beginning of time) and the last date it applies on (blank: no end). */
    public record RateRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal rate,
            LocalDate from, LocalDate to) {
    }

    /** A rate preview as the screen shows it: how many claims would show a different due, and the
     *  sum of the differences with two decimals. */
    public record RatePreviewView(int count, String diff) {
    }

    private final RateService service;
    private final RollupService rollups;
    private final ClaimService claims;

    public RateController(RateService service, RollupService rollups, ClaimService claims) {
        this.service = service;
        this.rollups = rollups;
        this.claims = claims;
    }

    /** The sheet's rates by grade, each grade's from the earliest; a grade with no rate is not listed.
     *  As they stand now, or as they stood at the end of the screen's as-of date. */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        return service.list(sheetId.trim(), AsOf.parse(asOf)).stream().map(RateView::of).toList();
    }

    /** The rates of the sheets the sheet's rates fall back to, nearest first (its parent, the
     *  parent's parent, up to three levels up), each listed as {@link #list} lists them. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        LocalDate day = AsOf.parse(asOf);
        return service.ancestors(sheetId.trim()).stream()
                .map(ancestor -> service.list(ancestor, day).stream().map(RateView::of).toList())
                .toList();
    }

    /** Set the rate for a grade (A, B or C) from a date, replacing the one it had from that date. */
    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated RateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return RateView.of(rollups.track(sheet, by, () -> service.set(sheet, by, grade, request.from(),
                request.to(), request.rate())));
    }

    /** Preview a candidate rate for a grade (A, B or C): how the dues of the OPEN and PENDING claims of
     *  people on the grade would change were it the grade's rate on every date. Nothing is saved. */
    @GetMapping("/{grade}/preview")
    public RatePreviewView preview(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String rate) {
        ClaimService.RatePreview preview = claims.previewRate(sheetId.trim(), grade, new BigDecimal(rate).setScale(2));
        return new RatePreviewView(preview.count(), preview.diff().toPlainString());
    }

    /** A rate that is not a number or a from-date that is not a real date is refused. */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }

    /** A to-date before the from-date is refused. */
    @ExceptionHandler(RateRefusedException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void refused() {
    }

    /** The grade's rate from that date was first set concurrently; caught by the unique index. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void conflict() {
    }
}
package net.officefloor.hq.app.rate;

/** A rate that cannot be set: its to-date is before its from-date. */
public class RateRefusedException extends RuntimeException {

    public RateRefusedException(String message) {
        super(message);
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, Injectable, computed, effect, inject, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface Rate {
  grade: string;
  /** A percent with two decimals, e.g. "12.50". */
  rate: string;
  /** The date the rate applies from (yyyy-mm-dd); null when it applies from the beginning of time. */
  from: string | null;
  /** The last date the rate applies on (yyyy-mm-dd); null when it has no end. */
  to: string | null;
}

export const GRADES = ['A', 'B', 'C'];

/** Shown for a due that has no rate to work from. */
export const NO_RATE = 'n/a';

/** The due on an amount in cents at a percent rate (two decimals), in cents: amount times rate
 *  divided by 100, rounded half up when `halfUp`, else half to even (a negative amount rounds as its
 *  opposite does). Worked in whole numbers so nothing is lost to floating point. */
export function dueCents(amountCents: number, rate: string, halfUp: boolean): number {
  if (amountCents < 0) return -dueCents(-amountCents, rate, halfUp);
  const hundredths = BigInt(Math.round(Number(rate) * 100));
  const product = BigInt(amountCents) * hundredths;
  const whole = product / 10000n;
  const rest = product % 10000n;
  return Number(rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole);
}

/** The rate in force on a date among a grade's rates: the one whose from-date is the latest on or
 *  before the date (no from-date applies from the beginning of time); null when none applies, or
 *  when that one's to-date is before the date. */
export function rateOn(rates: Rate[], date: string): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.from !== null && r.from > date) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to && best.to < date) return null;
  return best?.rate ?? null;
}

/** A grade a person was given, in force from its from-date. */
export interface PersonGrade {
  grade: string;
  /** The date the grade applies from (yyyy-mm-dd); null when it applies from the beginning of time,
   *  as the first grade a person was given does. */
  from: string | null;
}

/** The grade in force on a date among a person's grades: the one whose from-date is the latest on
 *  or before the date; null when none applies. */
export function gradeOn(grades: PersonGrade[], date: string): string | null {
  let best: PersonGrade | null = null;
  for (const g of grades) {
    if (g.from !== null && g.from > date) continue;
    if (best === null || (best.from ?? '') < (g.from ?? '')) best = g;
  }
  return best?.grade ?? null;
}

/** Rates in the order they are listed: by grade, then from the earliest. */
function byGradeAndFrom(a: Rate, b: Rate): number {
  return a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '');
}

/** Rates by grade, each grade's in the order given; a grade with no rate is absent. */
function byGradeOf(rates: Rate[]): Map<string, Rate[]> {
  const map = new Map<string, Rate[]>();
  for (const r of rates) map.set(r.grade, [...(map.get(r.grade) ?? []), r]);
  return map;
}

/** How a candidate rate would change the dues of a grade's open claims. */
export interface RatePreview {
  /** How many OPEN and PENDING claims would show a different due. */
  count: number;
  /** The sum of the differences (new due minus current due), two decimals. */
  diff: string;
}

const PERCENT = /^\d{1,5}(\.\d{1,2})?$/;

// The active sheet's rates for each grade, each from its from-date, and those of the sheets they fall
// back to (its parent, the parent's parent, up to three levels up), re-read whenever a sheet is loaded.
@Injectable({ providedIn: 'root' })
export class RateStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  /** The sheet's rates by grade, each grade's from the earliest. */
  readonly rates = signal<Rate[]>([]);
  /** The rates of the sheets the sheet's rates fall back to, nearest first, each listed as `rates`. */
  readonly inherited = signal<Rate[][]>([]);
  /** Each grade's rates by grade; a grade with no rate is absent. */
  readonly byGrade = computed(() => byGradeOf(this.rates()));
  /** Each fall-back sheet's rates by grade, nearest first. */
  private readonly inheritedByGrade = computed(() => this.inherited().map(byGradeOf));
  /** Each grade's rate in force on the sheet's today, falling back to the parent sheets'; a grade
   *  with none is absent. */
  readonly current = computed(() => {
    const today = this.session.today();
    const map = new Map<string, string>();
    if (!today) return map;
    for (const grade of GRADES) {
      const rate = rateOn(this.ofOn(grade, today), today);
      if (rate !== null) map.set(grade, rate);
    }
    return map;
  });

  /** A grade's rates; none when the grade has no rate. */
  of(grade: string): Rate[] {
    return this.byGrade().get(grade) ?? [];
  }

  /** A grade's rates to work a date's rate from: the sheet's own when one is in force on the date,
   *  else those of the nearest parent sheet with one in force on it; the sheet's own when none is. */
  ofOn(grade: string, date: string): Rate[] {
    const own = this.of(grade);
    if (rateOn(own, date) !== null) return own;
    for (const level of this.inheritedByGrade()) {
      const theirs = level.get(grade) ?? [];
      if (rateOn(theirs, date) !== null) return theirs;
    }
    return own;
  }

  /** The rates of a person's grade in force on a date to work the date's rate from (see ofOn); none
   *  when that grade has no rate. */
  ofGradeOn(grades: PersonGrade[], date: string): Rate[] {
    const grade = gradeOn(grades, date);
    return grade === null ? [] : this.ofOn(grade, date);
  }

  constructor() {
    effect(() => {
      const sheet = this.session.sheetId();
      const load = this.session.loads();
      this.rates.set([]);
      this.inherited.set([]);
      if (sheet) void this.read(sheet, load);
    });
  }

  /** Re-read the rates the active sheet falls back to: its parent sheet has changed. */
  async readInherited(): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const load = this.session.loads();
    const inherited = await firstValueFrom(
      this.http.get<Rate[][]>(`/api/sheets/${encodeURIComponent(sheet)}/rates/inherited`),
    );
    if (this.session.loads() !== load || this.session.sheetId() !== sheet) return;
    this.inherited.set(inherited);
  }

  /** Set a grade's rate from a date (null: from the beginning of time) through a date (null: no
   *  end) on the active sheet, replacing the one the grade had from that date. */
  async set(grade: string, rate: string, from: string | null, to: string | null): Promise<void> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    const saved = await firstValueFrom(
      this.http.put<Rate>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}`, { rate, from, to }),
    );
    if (this.session.sheetId() !== sheet) return;
    this.rates.update((list) =>
      [...list.filter((r) => r.grade !== saved.grade || r.from !== saved.from), saved].sort(byGradeAndFrom),
    );
  }

  /** Preview a candidate rate for a grade on the active sheet; nothing is saved. */
  async preview(grade: string, rate: string): Promise<RatePreview> {
    const sheet = this.session.sheetId();
    if (!sheet) throw new Error('No sheet loaded.');
    return firstValueFrom(
      this.http.get<RatePreview>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}/preview`, {
        params: { rate },
      }),
    );
  }

  private async read(sheet: string, load: number): Promise<void> {
    const [list, inherited] = await Promise.all([
      firstValueFrom(this.http.get<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`)),
      firstValueFrom(this.http.get<Rate[][]>(`/api/sheets/${encodeURIComponent(sheet)}/rates/inherited`)),
    ]);
    if (this.session.loads() !== load) return;
    this.rates.set(list);
    this.inherited.set(inherited);
  }
}

// The sheet's rate in force today for each grade, every rate with its from-date, and the form that
// sets one.
@Component({
  selector: 'app-rates',
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form (submit)="submit($event)">
        <label for="rate-form-grade">Grade</label>
        <select
          id="rate-form-grade"
          data-testid="rate-form-grade"
          [value]="grade()"
          (change)="grade.set(value($event)); error.set(null)"
        >
          @for (g of grades; track g) {
            <option [value]="g" [selected]="g === grade()">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input
          id="rate-form-pct"
          data-testid="rate-form-pct"
          inputmode="decimal"
          [value]="pct()"
          (input)="pct.set(value($event)); error.set(null)"
        />
        <label for="rate-form-from">From (blank: always)</label>
        <input
          id="rate-form-from"
          type="date"
          data-testid="rate-form-from"
          [value]="from()"
          (input)="from.set(value($event)); error.set(null)"
        />
        <label for="rate-form-to">To (blank: no end)</label>
        <input
          id="rate-form-to"
          type="date"
          data-testid="rate-form-to"
          [value]="to()"
          (input)="to.set(value($event)); error.set(null)"
        />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
      </form>
      @if (error(); as message) {
        <p role="alert" data-testid="rate-form-error">{{ message }}</p>
      }
      <form (submit)="runPreview($event)">
        <label for="rate-preview-grade">Preview grade</label>
        <select
          id="rate-preview-grade"
          data-testid="rate-preview-grade"
          [value]="previewGrade()"
          (change)="previewGrade.set(value($event)); previewChanged()"
        >
          @for (g of grades; track g) {
            <option [value]="g" [selected]="g === previewGrade()">{{ g }}</option>
          }
        </select>
        <label for="rate-preview-pct">Candidate rate (%)</label>
        <input
          id="rate-preview-pct"
          data-testid="rate-preview-pct"
          inputmode="decimal"
          [value]="previewPct()"
          (input)="previewPct.set(value($event)); previewChanged()"
        />
        <button type="submit" data-testid="rate-preview">Preview</button>
      </form>
      @if (previewError(); as message) {
        <p role="alert" data-testid="rate-preview-error">{{ message }}</p>
      }
      @if (previewResult(); as result) {
        <p>
          Claims that would change: <span data-testid="rate-preview-count">{{ result.count }}</span>;
          difference: <span data-testid="rate-preview-diff">{{ result.diff }}</span>
        </p>
      }
      <table>
        <caption>In force today</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          @for (g of grades; track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ store.current().get(g) ?? noRate }}</td>
            </tr>
          }
        </tbody>
      </table>
      <table>
        <caption>All rates</caption>
        <thead>
          <tr>
            <th scope="col">Grade</th>
            <th scope="col">From</th>
            <th scope="col">To</th>
            <th scope="col">Rate (%)</th>
          </tr>
        </thead>
        <tbody>
          @for (r of store.rates(); track r.grade + '-' + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? 'always' }}</td>
              <td data-testid="rate-to">{{ r.to ?? '' }}</td>
              <td data-testid="rate-pct">{{ r.rate }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  protected readonly store = inject(RateStore);
  protected readonly grades = GRADES;
  protected readonly noRate = NO_RATE;
  protected readonly grade = signal('A');
  protected readonly pct = signal('');
  protected readonly from = signal('');
  protected readonly to = signal('');
  protected readonly error = signal<string | null>(null);
  protected readonly previewGrade = signal('A');
  protected readonly previewPct = signal('');
  protected readonly previewError = signal<string | null>(null);
  protected readonly previewResult = signal<RatePreview | null>(null);
  /** Whether a submit is waiting for its answer; a second submit meanwhile is dropped. */
  private readonly busy = signal(false);

  protected value(event: Event): string {
    return (event.target as HTMLInputElement | HTMLSelectElement).value;
  }

  /** A changed grade or rate drops the last preview and its error: they were for the old one. */
  protected previewChanged(): void {
    this.previewError.set(null);
    this.previewResult.set(null);
  }

  protected async runPreview(event: Event): Promise<void> {
    event.preventDefault();
    this.previewError.set(null);
    this.previewResult.set(null);
    const pct = this.previewPct().trim();
    if (!PERCENT.test(pct)) {
      this.previewError.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    try {
      this.previewResult.set(await this.store.preview(this.previewGrade(), pct));
    } catch {
      this.previewError.set('The rate could not be previewed.');
    }
  }

  protected async submit(event: Event): Promise<void> {
    event.preventDefault();
    if (this.busy()) return;
    this.error.set(null);
    const pct = this.pct().trim();
    if (!PERCENT.test(pct)) {
      this.error.set('Type a rate of 0.00 or more, with up to two decimals.');
      return;
    }
    const from = this.from().trim() || null;
    const to = this.to().trim() || null;
    if (from !== null && to !== null && to < from) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    this.busy.set(true);
    try {
      await this.store.set(this.grade(), pct, from, to);
    } catch {
      this.error.set('The rate could not be set.');
    } finally {
      this.busy.set(false);
    }
  }
}

