package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates set on a sheet for each grade, each in force from its from-date. A grade with no rate
 *  in force on a date on a sheet takes its parent sheet's, then the parent's parent's, up to
 *  {@link #PARENT_LEVELS} levels up. */
@Service
public class RateService {

    /** How many levels of parent sheets are looked to for a rate the sheet has none in force for. */
    public static final int PARENT_LEVELS = 3;

    private final RateRepository rates;
    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final History history;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, SheetRepository sheetRepository, History history,
            Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.history = history;
        this.audit = audit;
    }

    /** The sheet's parent sheet's id; null when it has none. The parent is not kept in the sheet's
     *  history: a sheet shown as of a past day falls back to its parent as it stands now. */
    private String parentOf(String sheetId) {
        return sheetRepository.findById(sheetId).map(Sheet::getParentId).orElse(null);
    }

    /** The sheets the sheet's rates fall back to, nearest first: its parent, the parent's parent, up
     *  to {@link #PARENT_LEVELS} levels up. */
    public List<String> ancestors(String sheetId) {
        List<String> found = new ArrayList<>();
        String sheet = parentOf(sheetId);
        while (sheet != null && found.size() < PARENT_LEVELS && !sheet.equals(sheetId) && !found.contains(sheet)) {
            found.add(sheet);
            sheet = parentOf(sheet);
        }
        return found;
    }

    /** The sheet's rates by grade, each grade's from the earliest. */
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromAscIdAsc(sheetId);
    }

    /** The sheet's rates by grade, each grade's from the earliest, as they stood at the end of a day
     *  (null: as they stand now). */
    public List<Rate> list(String sheetId, LocalDate asOf) {
        if (asOf == null) {
            return list(sheetId);
        }
        return Stream.of("A", "B", "C")
                .flatMap(grade -> history.rates(sheetId, grade, asOf).stream()
                        .sorted(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()))))
                .toList();
    }

    /** The grade's rate in force on a date: the one whose from-date is the latest on or before it
     *  (a rate with no from-date applies from the beginning of time); none applies when there is no
     *  such rate, or when that one's to-date is before the date. When none applies on the sheet, the
     *  parent sheet's is taken, then the parent's parent's, up to {@link #PARENT_LEVELS} levels up;
     *  empty when none applies on any of them. */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return rateOn(sheetId, grade, date, null);
    }

    /** The grade's rate in force on a date as the rates (the sheet's and its parent sheets') stood
     *  at the end of a day (null: as they stand now). */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        Optional<Rate> own = ownRateOn(sheetId, grade, date, asOf);
        if (own.isPresent()) {
            return own;
        }
        for (String ancestor : ancestors(sheetId)) {
            Optional<Rate> theirs = ownRateOn(ancestor, grade, date, asOf);
            if (theirs.isPresent()) {
                return theirs;
            }
        }
        return Optional.empty();
    }

    private Optional<Rate> ownRateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        return inForce(asOf == null ? rates.findBySheetIdAndGradeOrderByFromAsc(sheetId, grade)
                : history.rates(sheetId, grade, asOf), date);
    }

    private static Optional<Rate> inForce(List<Rate> theirs, LocalDate date) {
        return theirs.stream()
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(rate -> !rate.endedBy(date));
    }

    /** Set the rate for a grade from a date (null: from the beginning of time) through a date (null:
     *  with no end), replacing the one the grade had from that date. A to-date before the from-date
     *  is refused. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId);
        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
        Optional<Rate> had = from == null
                ? rates.findBySheetIdAndGradeAndFromIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from);
        Rate saved = had
                .map(existing -> {
                    existing.setRate(scaled);
                    existing.setTo(to);
                    return existing;
                })
                .orElseGet(() -> new Rate(sheetId, grade, from, to, scaled));
        saved = rates.saveAndFlush(saved);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + saved.getRate().toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        return saved;
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.rollup.RollupService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** A grade's rate as the screen shows it; the rate is a percent string with two decimals, the
     *  from-date null when the rate applies from the beginning of time. */
    public record RateView(String grade, String rate, LocalDate from, LocalDate to) {
        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getRate().toPlainString(), rate.getFrom(), rate.getTo());
        }
    }

    /** A rate: a percent of 0.00 or more with up to two decimals, and the date it applies from
     *  (blank: from the beginning of time) and the last date it applies on (blank: no end). */
    public record RateRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 5, fraction = 2) BigDecimal rate,
            LocalDate from, LocalDate to) {
    }

    /** A rate preview as the screen shows it: how many claims would show a different due, and the
     *  sum of the differences with two decimals. */
    public record RatePreviewView(int count, String diff) {
    }

    private final RateService service;
    private final RollupService rollups;
    private final ClaimService claims;

    public RateController(RateService service, RollupService rollups, ClaimService claims) {
        this.service = service;
        this.rollups = rollups;
        this.claims = claims;
    }

    /** The sheet's rates by grade, each grade's from the earliest; a grade with no rate is not listed.
     *  As they stand now, or as they stood at the end of the screen's as-of date. */
    @GetMapping
    public List<RateView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        return service.list(sheetId.trim(), AsOf.parse(asOf)).stream().map(RateView::of).toList();
    }

    /** The rates of the sheets the sheet's rates fall back to, nearest first (its parent, the
     *  parent's parent, up to three levels up), each listed as {@link #list} lists them. */
    @GetMapping("/inherited")
    public List<List<RateView>> inherited(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(value = AsOf.HEADER, required = false) String asOf) {
        LocalDate day = AsOf.parse(asOf);
        return service.ancestors(sheetId.trim()).stream()
                .map(ancestor -> service.list(ancestor, day).stream().map(RateView::of).toList())
                .toList();
    }

    /** Set the rate for a grade (A, B or C) from a date, replacing the one it had from that date. */
    @PutMapping("/{grade}")
    public RateView set(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated RateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return RateView.of(rollups.track(sheet, by, () -> service.set(sheet, by, grade, request.from(),
                request.to(), request.rate())));
    }

    /** Preview a candidate rate for a grade (A, B or C): how the dues of the OPEN and PENDING claims of
     *  people on the grade would change were it the grade's rate on every date. Nothing is saved. */
    @GetMapping("/{grade}/preview")
    public RatePreviewView preview(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestParam @Pattern(regexp = "\\d{1,5}(\\.\\d{1,2})?") String rate) {
